        String scheduleKey = key("SCH");
        createPlan(scheduleKey, occ("G1", key("SEC"), iso(8), iso(9)));

        // 版本不匹配
        mvc.perform(put("/api/v1/plans/{key}/occupancies", scheduleKey)
