        createPlan(scheduleKey, occ("G1", key("SEC"), iso(10), iso(11)));
        // 按 [B, A] 顺序登记，响应保持提交顺序，crew-check 按人员 ID 稳定升序
        publishPlan(scheduleKey, key("REQ"), memberB, memberA);

